{
  "version": 3,
  "sources": ["src/app/features/calendar/components/event-detail/event-detail.component.scss"],
  "sourcesContent": [".event-detail {\n  background: #fff;\n  border-radius: 8px;\n  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);\n  width: 380px;\n  max-height: 500px;\n  overflow-y: auto;\n  z-index: 1000;\n  border-left: 3px solid var(--event-color, #1976d2);\n  animation: eventDetailIn 0.15s ease-out;\n\n  &__header {\n    display: flex;\n    align-items: flex-start;\n    padding: 16px 8px 8px 16px;\n    gap: 8px;\n  }\n\n  &__color-dot {\n    width: 12px;\n    height: 12px;\n    border-radius: 50%;\n    flex-shrink: 0;\n    margin-top: 6px;\n  }\n\n  &__title {\n    flex: 1;\n    font-size: 18px;\n    font-weight: 400;\n    color: #3c4043;\n    margin: 0;\n    line-height: 1.4;\n    word-break: break-word;\n  }\n\n  &__actions {\n    display: flex;\n    gap: 0;\n    flex-shrink: 0;\n\n    button {\n      width: 32px;\n      height: 32px;\n      line-height: 32px;\n\n      ::ng-deep .mat-icon {\n        font-size: 18px;\n        width: 18px;\n        height: 18px;\n        color: #5f6368;\n      }\n    }\n  }\n\n  &__row {\n    display: flex;\n    align-items: flex-start;\n    padding: 4px 16px;\n    gap: 12px;\n\n    &--guests {\n      align-items: flex-start;\n    }\n  }\n\n  &__icon {\n    color: #5f6368;\n    font-size: 18px;\n    width: 18px;\n    height: 18px;\n    flex-shrink: 0;\n    margin-top: 2px;\n  }\n\n  &__info {\n    display: flex;\n    flex-direction: column;\n  }\n\n  &__datetime {\n    font-size: 13px;\n    color: #3c4043;\n  }\n\n  &__recurrence {\n    font-size: 12px;\n    color: #70757a;\n    margin-top: 2px;\n  }\n\n  &__location {\n    font-size: 13px;\n    color: #3c4043;\n  }\n\n  &__video-link {\n    font-size: 13px;\n    color: #1a73e8;\n    text-decoration: none;\n\n    &:hover {\n      text-decoration: underline;\n    }\n  }\n\n  &__guests {\n    flex: 1;\n  }\n\n  &__guest-count {\n    font-size: 13px;\n    color: #3c4043;\n    font-weight: 500;\n    margin-bottom: 4px;\n  }\n\n  &__guest {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    padding: 2px 0;\n  }\n\n  &__guest-status {\n    font-size: 14px !important;\n    width: 14px !important;\n    height: 14px !important;\n  }\n\n  &__guest-name {\n    font-size: 12px;\n    color: #3c4043;\n  }\n\n  &__guest-email {\n    font-size: 11px;\n    color: #70757a;\n  }\n\n  &__description-wrapper {\n    flex: 1;\n    min-width: 0;\n  }\n\n  &__description {\n    font-size: 13px;\n    color: #3c4043;\n    margin: 0;\n    white-space: pre-line;\n    word-break: break-word;\n  }\n\n  &__more-btn {\n    background: none;\n    border: none;\n    color: #1a73e8;\n    font-size: 12px;\n    cursor: pointer;\n    padding: 2px 0;\n\n    &:hover {\n      text-decoration: underline;\n    }\n  }\n\n  &__schecon-badge {\n    font-size: 12px;\n    color: #4caf50;\n    font-weight: 500;\n    background-color: #e8f5e9;\n    padding: 2px 8px;\n    border-radius: 12px;\n  }\n\n  &__rsvp {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 12px 16px;\n    border-top: 1px solid #e0e0e0;\n    margin-top: 8px;\n  }\n\n  &__rsvp-label {\n    font-size: 13px;\n    color: #5f6368;\n    flex-shrink: 0;\n  }\n\n  &__rsvp-buttons {\n    display: flex;\n    gap: 6px;\n  }\n\n  &__rsvp-btn {\n    border: 1px solid #dadce0;\n    background: #fff;\n    border-radius: 4px;\n    padding: 4px 12px;\n    font-size: 12px;\n    cursor: pointer;\n    transition: background-color 0.15s;\n\n    &--accept:hover {\n      background-color: #e8f5e9;\n      border-color: #4caf50;\n      color: #4caf50;\n    }\n\n    &--tentative:hover {\n      background-color: #fff3e0;\n      border-color: #ff9800;\n      color: #ff9800;\n    }\n\n    &--decline:hover {\n      background-color: #fbe9e7;\n      border-color: #f44336;\n      color: #f44336;\n    }\n  }\n\n  &__footer {\n    padding: 8px 16px 12px;\n  }\n\n  // === Entrance animation ===\n}\n\n@keyframes eventDetailIn {\n  from {\n    opacity: 0;\n    transform: scale(0.95);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1);\n  }\n}\n\n.event-detail {\n  /* === メール招待 UI (ユーザー指示 2026-04-21) === */\n  &__invite {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    margin-top: 8px;\n    padding-top: 8px;\n    border-top: 1px dashed #e0e0e0;\n  }\n\n  &__invite-input {\n    flex: 1;\n    min-width: 0;\n    font-family: inherit;\n    font-size: 12px;\n    color: #3c4043;\n    padding: 6px 10px;\n    border: 1px solid #dadce0;\n    border-radius: 18px;\n    outline: none;\n    background: #fafafa;\n    transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;\n\n    &:focus {\n      background: #fff;\n      border-color: #ff9800;\n      box-shadow: 0 0 0 2px rgba(255, 152, 0, 0.15);\n    }\n\n    &::placeholder {\n      color: #9aa0a6;\n    }\n  }\n\n  &__invite-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: 4px;\n    padding: 6px 10px;\n    border: 1px solid #ff9800;\n    background: #fff3e0;\n    color: #e87f03;\n    border-radius: 18px;\n    font-size: 12px;\n    font-weight: 500;\n    cursor: pointer;\n    transition: background-color 0.15s, color 0.15s;\n    flex-shrink: 0;\n\n    mat-icon {\n      font-size: 14px;\n      width: 14px;\n      height: 14px;\n    }\n\n    &:hover:not(:disabled) {\n      background: #ff9800;\n      color: #fff;\n    }\n\n    &:disabled {\n      opacity: 0.5;\n      cursor: not-allowed;\n    }\n  }\n\n  &__invite-hint {\n    margin-top: 4px;\n    font-size: 11px;\n    color: #f44336;\n  }\n\n  &__notify-btn {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    background: none;\n    border: 1px solid #dadce0;\n    border-radius: 4px;\n    padding: 6px 12px;\n    font-size: 12px;\n    color: #5f6368;\n    cursor: pointer;\n    transition: background-color 0.15s;\n\n    mat-icon {\n      font-size: 16px;\n      width: 16px;\n      height: 16px;\n    }\n\n    &:hover {\n      background-color: #f1f3f4;\n    }\n  }\n}\n"],
  "mappings": ";;;AAAA,CAAA;AACE,cAAA;AACA,iBAAA;AACA,cAAA,EAAA,IAAA,KAAA,KAAA,CAAA,EAAA,CAAA,EAAA,CAAA,EAAA;AACA,SAAA;AACA,cAAA;AACA,cAAA;AACA,WAAA;AACA,eAAA,IAAA,MAAA,IAAA,aAAA,EAAA;AACA,aAAA,cAAA,MAAA;;AAEA,CAAA;AACE,WAAA;AACA,eAAA;AACA,WAAA,KAAA,IAAA,IAAA;AACA,OAAA;;AAGF,CAAA;AACE,SAAA;AACA,UAAA;AACA,iBAAA;AACA,eAAA;AACA,cAAA;;AAGF,CAAA;AACE,QAAA;AACA,aAAA;AACA,eAAA;AACA,SAAA;AACA,UAAA;AACA,eAAA;AACA,cAAA;;AAGF,CAAA;AACE,WAAA;AACA,OAAA;AACA,eAAA;;AAEA,CALF,sBAKE;AACE,SAAA;AACA,UAAA;AACA,eAAA;;AAEA,CAVJ,sBAUI,OAAA,UAAA,CAAA;AACE,aAAA;AACA,SAAA;AACA,UAAA;AACA,SAAA;;AAKN,CAAA;AACE,WAAA;AACA,eAAA;AACA,WAAA,IAAA;AACA,OAAA;;AAEA,CAAA;AACE,eAAA;;AAIJ,CAAA;AACE,SAAA;AACA,aAAA;AACA,SAAA;AACA,UAAA;AACA,eAAA;AACA,cAAA;;AAGF,CAAA;AACE,WAAA;AACA,kBAAA;;AAGF,CAAA;AACE,aAAA;AACA,SAAA;;AAGF,CAAA;AACE,aAAA;AACA,SAAA;AACA,cAAA;;AAGF,CAAA;AACE,aAAA;AACA,SAAA;;AAGF,CAAA;AACE,aAAA;AACA,SAAA;AACA,mBAAA;;AAEA,CALF,wBAKE;AACE,mBAAA;;AAIJ,CAAA;AACE,QAAA;;AAGF,CAAA;AACE,aAAA;AACA,SAAA;AACA,eAAA;AACA,iBAAA;;AAGF,CAAA;AACE,WAAA;AACA,eAAA;AACA,OAAA;AACA,WAAA,IAAA;;AAGF,CAAA;AACE,aAAA;AACA,SAAA;AACA,UAAA;;AAGF,CAAA;AACE,aAAA;AACA,SAAA;;AAGF,CAAA;AACE,aAAA;AACA,SAAA;;AAGF,CAAA;AACE,QAAA;AACA,aAAA;;AAGF,CAAA;AACE,aAAA;AACA,SAAA;AACA,UAAA;AACA,eAAA;AACA,cAAA;;AAGF,CAAA;AACE,cAAA;AACA,UAAA;AACA,SAAA;AACA,aAAA;AACA,UAAA;AACA,WAAA,IAAA;;AAEA,CARF,sBAQE;AACE,mBAAA;;AAIJ,CAAA;AACE,aAAA;AACA,SAAA;AACA,eAAA;AACA,oBAAA;AACA,WAAA,IAAA;AACA,iBAAA;;AAGF,CAAA;AACE,WAAA;AACA,eAAA;AACA,OAAA;AACA,WAAA,KAAA;AACA,cAAA,IAAA,MAAA;AACA,cAAA;;AAGF,CAAA;AACE,aAAA;AACA,SAAA;AACA,eAAA;;AAGF,CAAA;AACE,WAAA;AACA,OAAA;;AAGF,CAAA;AACE,UAAA,IAAA,MAAA;AACA,cAAA;AACA,iBAAA;AACA,WAAA,IAAA;AACA,aAAA;AACA,UAAA;AACA,cAAA,iBAAA;;AAEA,CAAA,8BAAA;AACE,oBAAA;AACA,gBAAA;AACA,SAAA;;AAGF,CAAA,iCAAA;AACE,oBAAA;AACA,gBAAA;AACA,SAAA;;AAGF,CAAA,+BAAA;AACE,oBAAA;AACA,gBAAA;AACA,SAAA;;AAIJ,CAAA;AACE,WAAA,IAAA,KAAA;;AAMJ,WA7NE;AA8NA;AACE,aAAA;AACA,eAAA,MAAA;;AAEF;AACE,aAAA;AACA,eAAA,MAAA;;;AAIJ,CAjPA;;AAmPE,CAAA;AACE,WAAA;AACA,eAAA;AACA,OAAA;