ay: flex;\n    align-items: center;\n    justify-content: space-between;\n    padding: 16px 20px;\n    border-bottom: 1px solid #e0e0e0;\n\n    h3 {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      margin: 0;\n      font-size: 16px;\n      font-weight: 600;\n      color: #3c4043;\n\n      mat-icon {\n        font-size: 20px;\n        width: 20px;\n        height: 20px;\n        color: #ff9800;\n      }\n    }\n  }\n\n  &__modal-close {\n    background: none;\n    border: none;\n    cursor: pointer;\n    color: #5f6368;\n    padding: 4px;\n    border-radius: 50%;\n    width: 32px;\n    height: 32px;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n\n    &:hover { background: #f1f3f4; }\n  }\n\n  &__modal-my-rsvp {\n    padding: 14px 20px;\n    background: #fafafa;\n    border-bottom: 1px solid #e0e0e0;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n    flex-wrap: wrap;\n  }\n\n  &__modal-my-rsvp-label {\n    font-size: 13px;\n    color: #5f6368;\n    font-weight: 500;\n  }\n\n  &__modal-tabs {\n    display: flex;\n    border-bottom: 1px solid #e0e0e0;\n  }\n  &__modal-tab {\n    flex: 1;\n    padding: 12px;\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-size: 13px;\n    color: #5f6368;\n    border-bottom: 2px solid transparent;\n    transition: background 0.15s, color 0.15s, border-color 0.15s;\n\n    &:hover { background: #fafafa; }\n\n    &--active {\n      color: #ff9800;\n      font-weight: 600;\n      border-bottom-color: #ff9800;\n    }\n  }\n\n  &__modal-body {\n    flex: 1;\n    overflow-y: auto;\n    padding: 8px 0;\n  }\n\n  &__modal-participant {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n    padding: 10px 20px;\n    transition: background 0.15s;\n\n    &:hover { background: #fafafa; }\n  }\n\n  &__modal-participant-info {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    gap: 2px;\n    min-width: 0;\n  }\n  &__modal-participant-name {\n    font-size: 14px;\n    color: #3c4043;\n    font-weight: 500;\n  }\n  &__modal-participant-rsvp {\n    font-size: 11px;\n    color: #9e9e9e;\n    align-self: flex-start;\n    padding: 2px 8px;\n    border-radius: 10px;\n    background: #f5f5f5;\n\n    &--going { background: #e8f5e9; color: #2e7d32; }\n    &--maybe { background: #fff3e0; color: #e65100; }\n  }\n\n  &__modal-empty {\n    padding: 20px;\n    text-align: center;\n    color: #9e9e9e;\n    font-size: 13px;\n  }\n}\n\n@keyframes event-detail-modal-in {\n  from { opacity: 0; transform: scale(0.95); }\n  to { opacity: 1; transform: scale(1); }\n}\n\n/* スマホではフルスクリーン寄せ */\n@media (max-width: 767px) {\n  .event-detail {\n    &__modal {\n      max-width: 100%;\n      max-height: 92dvh;\n    }\n  }\n}\n"],
